#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT_LEN 1024

int main(int argc, char *argv[])
{
    const char *input = "";
    size_t input_len = 0;

    if (argc == 2) {
        input = argv[1];
        input_len = strlen(input);
    } else if (argc > 2) {
        input = argv[1];
        input_len = strlen(input);
    } else {
        input = "";
        input_len = 0;
    }

    if (input_len > MAX_INPUT_LEN) {
        puts("TOO_LONG");
        return 0;
    }

    char norm[MAX_INPUT_LEN + 1];
    size_t norm_len = 0;
    for (size_t i = 0; i < input_len; ++i) {
        unsigned char ch = (unsigned char)input[i];
        if (isalnum(ch)) {
            norm[norm_len++] = (char)toupper(ch);
        }
    }
    norm[norm_len] = '\0';

    int is_pal = 1;
    for (size_t i = 0; i < norm_len / 2; ++i) {
        if (norm[i] != norm[norm_len - 1 - i]) {
            is_pal = 0;
            break;
        }
    }

    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
